<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user = app_require_permission('wholesale.view');
$canManage = app_has_permission('wholesale.manage',$user);
?>
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">
<title>Wholesale Gelato Pipeline</title>
<style>
:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6d716b;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--good:#157347;--warn:#9a6200;--bad:#a62a24;--shadow:0 15px 40px rgba(25,26,22,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.topbar{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:12px}.logo{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:var(--dark);color:#fff;font-weight:900}.brand strong{display:block}.brand small{display:block;color:var(--muted)}.top-actions{display:flex;gap:8px}.btn{min-height:38px;border:1px solid var(--line);border-radius:10px;padding:8px 12px;background:#fff;color:var(--ink);font-weight:800;text-decoration:none}.btn.primary{border-color:var(--accent);background:var(--accent);color:#fff}.shell{padding:24px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:18px}.head h1{margin:4px 0 0;font-size:38px;letter-spacing:-.05em}.eyebrow{margin:0;color:var(--accent);font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.13em}.head p:last-child{max-width:760px;margin:8px 0 0;color:var(--muted)}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}.kpi{padding:14px;border:1px solid var(--line);border-radius:16px;background:#fff}.kpi small{display:block;color:var(--muted);font-size:9px;font-weight:900;text-transform:uppercase}.kpi strong{display:block;margin-top:6px;font-size:26px}.toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 180px auto;gap:8px;margin-bottom:15px}.field{width:100%;min-height:40px;border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#fff}.board-wrap{overflow:auto;padding-bottom:24px}.board{display:grid;grid-template-columns:repeat(7,minmax(260px,1fr));gap:12px;min-width:1900px;align-items:start}.column{min-height:400px;padding:10px;border:1px solid var(--line);border-radius:16px;background:#e9e8e4}.column.drag-over{outline:3px solid rgba(217,74,43,.25)}.column-head{display:flex;align-items:center;justify-content:space-between;padding:5px 5px 10px}.column-head strong{text-transform:capitalize}.column-head span{min-width:25px;padding:4px 7px;border-radius:999px;background:#fff;text-align:center;font-size:10px;font-weight:900}.cards{display:grid;gap:8px}.lead-card{padding:13px;border:1px solid #d8d8d2;border-radius:13px;background:#fff;box-shadow:0 5px 14px rgba(25,26,22,.04);cursor:pointer}.lead-card[draggable="true"]{cursor:grab}.lead-card h3{margin:0 0 5px;font-size:14px}.lead-card p{margin:0;color:var(--muted);font-size:10px;line-height:1.45}.chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.chip{padding:4px 6px;border-radius:999px;background:#f1f0ec;color:#5f635d;font-size:8px;font-weight:900}.lead-meta{display:flex;justify-content:space-between;gap:8px;margin-top:10px;padding-top:9px;border-top:1px solid #ecece8;font-size:9px;color:var(--muted)}.empty{padding:30px 12px;text-align:center;color:#8b8e89;font-size:11px;border:1px dashed #c9c9c2;border-radius:12px}.drawer{position:fixed;top:0;right:-580px;width:min(560px,96vw);height:100vh;z-index:50;background:#fff;border-left:1px solid var(--line);box-shadow:-20px 0 50px rgba(0,0,0,.14);transition:.2s;overflow:auto}.drawer.open{right:0}.drawer-head{position:sticky;top:0;display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:20px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.96);backdrop-filter:blur(10px);z-index:2}.drawer-head h2{margin:5px 0 0;font-size:25px}.drawer-body{padding:20px}.close{border:0;background:#f1f1ee;width:38px;height:38px;border-radius:10px;font-size:20px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.detail{padding:10px;border-radius:11px;background:#f6f5f2}.detail small{display:block;color:var(--muted);font-size:8px;font-weight:900;text-transform:uppercase}.detail strong,.detail span{display:block;margin-top:4px;font-size:11px;line-height:1.4;word-break:break-word}.section{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.section h3{margin:0 0 10px;font-size:14px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.form-grid .wide{grid-column:1/-1}.activity-list{display:grid;gap:8px}.activity{padding:10px;border:1px solid var(--line);border-radius:11px}.activity strong{font-size:10px}.activity p{margin:4px 0 0;color:var(--muted);font-size:10px;line-height:1.45}.activity small{display:block;margin-top:5px;color:#8a8d87;font-size:8px}.toast{position:fixed;right:20px;bottom:20px;z-index:80;padding:11px 14px;border-radius:11px;background:#171b1a;color:#fff;font-size:11px;box-shadow:var(--shadow)}.hidden{display:none}@media(max-width:800px){.summary{grid-template-columns:1fr 1fr}.toolbar{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}.detail-grid,.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}}
</style>
</head>
<body>
<header class="topbar"><div class="brand"><div class="logo">G</div><div><strong>Wholesale Gelato Pipeline</strong><small>Restaurant AI operations</small></div></div><div class="top-actions"><?php if($canManage): ?><a class="btn" href="wholesale-purchasing.php">Purchasing Planner</a><?php endif; ?><a class="btn" href="recipes.php">Recipe Library</a><a class="btn" href="wholesale.php" target="_blank">Public Form ↗</a><a class="btn" href="index.php">Workspace</a></div></header>
<main class="shell"><div class="head"><div><p class="eyebrow">Foodservice sales</p><h1>Wholesale pipeline</h1><p>Every public gelato inquiry lands here. Qualify the buyer, schedule samples, build pricing, track follow-up, and give the private restaurant Agent a complete sales context.</p></div><button class="btn primary" id="refresh">Refresh pipeline</button></div>
<div class="summary"><div class="kpi"><small>Open opportunities</small><strong id="openCount">0</strong></div><div class="kpi"><small>Pipeline value</small><strong id="pipelineValue">$0</strong></div><div class="kpi"><small>Weighted value</small><strong id="weightedValue">$0</strong></div><div class="kpi"><small>Won accounts</small><strong id="wonCount">0</strong></div></div>
<div class="toolbar"><input class="field" id="search" placeholder="Search business, contact, email, flavor, or notes..."><select class="field" id="stageFilter"><option value="">All stages</option></select><button class="btn" id="clearSearch">Clear</button></div>
<div class="board-wrap"><div class="board" id="board"></div></div></main>
<aside class="drawer" id="drawer"><div class="drawer-head"><div><p class="eyebrow">Wholesale opportunity</p><h2 id="drawerTitle">Lead</h2></div><button class="close" id="drawerClose">×</button></div><div class="drawer-body" id="drawerBody"></div></aside>
<div class="toast hidden" id="toast"></div>
<script>window.WHOLESALE_CONFIG={csrf:<?= json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,canManage:<?= $canManage?'true':'false' ?>};</script>
<script>
(()=>{const cfg=window.WHOLESALE_CONFIG,stages=['new','qualified','sample','quoted','negotiation','won','lost'],labels={new:'New',qualified:'Qualified',sample:'Sample',quoted:'Quoted',negotiation:'Negotiation',won:'Won',lost:'Lost'};let leads=[],users=[],activeId='';const esc=v=>String(v??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));const money=v=>'$'+Number(v||0).toLocaleString(undefined,{maximumFractionDigits:0});const toast=t=>{const e=document.getElementById('toast');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),1800)};async function api(url,options={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(options.headers||{})},...options});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed.');return d}
async function load(){const [list,summary]=await Promise.all([api('api/wholesale.php?action=list'),api('api/wholesale.php?action=summary')]);leads=list.leads||[];users=summary.users||[];renderSummary(summary.summary||[]);renderBoard();if(activeId)openLead(activeId)}
function renderSummary(rows){const by=Object.fromEntries(rows.map(r=>[r.pipeline_stage,r]));const open=stages.filter(s=>!['won','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.lead_count||0),0);const value=stages.filter(s=>!['won','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.value_total||0),0);const weighted=stages.filter(s=>!['won','lost'].includes(s)).reduce((n,s)=>n+Number(by[s]?.weighted_value||0),0);document.getElementById('openCount').textContent=open;document.getElementById('pipelineValue').textContent=money(value);document.getElementById('weightedValue').textContent=money(weighted);document.getElementById('wonCount').textContent=Number(by.won?.lead_count||0)}
function renderBoard(){const q=document.getElementById('search').value.trim().toLowerCase(),filter=document.getElementById('stageFilter').value;const filtered=leads.filter(l=>(!filter||l.stage===filter)&&(!q||[l.businessName,l.contactName,l.email,l.businessType,l.flavorsInterest,l.notes].join(' ').toLowerCase().includes(q)));document.getElementById('board').innerHTML=stages.map(stage=>{const items=filtered.filter(l=>l.stage===stage);return `<section class="column" data-stage="${stage}"><div class="column-head"><strong>${labels[stage]}</strong><span>${items.length}</span></div><div class="cards">${items.length?items.map(card).join(''):'<div class="empty">No opportunities</div>'}</div></section>`}).join('');document.querySelectorAll('.lead-card').forEach(card=>{card.addEventListener('click',()=>openLead(card.dataset.id));if(cfg.canManage){card.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',card.dataset.id))}});if(cfg.canManage)document.querySelectorAll('.column').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over')});col.addEventListener('dragleave',()=>col.classList.remove('drag-over'));col.addEventListener('drop',async e=>{e.preventDefault();col.classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain');if(id)await moveStage(id,col.dataset.stage)})})}
function card(l){const chips=[l.businessType,l.estimatedMonthlyVolume,l.privateLabelInterest?'Private label':''].filter(Boolean);return `<article class="lead-card" data-id="${esc(l.id)}" draggable="${cfg.canManage?'true':'false'}"><h3>${esc(l.businessName)}</h3><p>${esc(l.contactName)} · ${esc(l.location||l.email)}</p><div class="chips">${chips.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}</div><div class="lead-meta"><span>${l.estimatedValue!=null?money(l.estimatedValue):'Value TBD'}</span><span>${l.probability}%</span></div></article>`}
async function moveStage(id,stage){await api('api/wholesale.php',{method:'POST',body:JSON.stringify({action:'stage',id,stage,csrf_token:cfg.csrf})});toast('Stage updated');await load()}
async function openLead(id){activeId=id;const d=await api('api/wholesale.php?action=detail&id='+encodeURIComponent(id)),l=d.lead;document.getElementById('drawerTitle').textContent=l.businessName;document.getElementById('drawer').classList.add('open');document.getElementById('drawerBody').innerHTML=`<div class="detail-grid">${[['Contact',l.contactName],['Email',l.email],['Phone',l.phone||'—'],['Type',l.businessType||'—'],['Location',l.location||'—'],['Volume',l.estimatedMonthlyVolume||'—'],['Frequency',l.orderFrequency||'—'],['Fulfillment',l.fulfillmentPreference||'—'],['Freezer',l.freezerCapacity||'—'],['Desired start',l.desiredStartDate||'—'],['Current supplier',l.currentSupplier||'—'],['Private label',l.privateLabelInterest?'Yes':'No']].map(x=>`<div class="detail"><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join('')}</div><div class="section"><h3>Flavor / program interest</h3><p style="white-space:pre-wrap;color:var(--muted);font-size:12px;line-height:1.55">${esc(l.flavorsInterest||'No flavor notes yet.')}</p><div class="chips">${(l.packageSizes||[]).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div></div>${cfg.canManage?editForm(l):''}<div class="section"><h3>Activity</h3>${cfg.canManage?activityForm():''}<div class="activity-list" style="margin-top:10px">${(d.activities||[]).length?(d.activities||[]).map(a=>`<article class="activity"><strong>${esc(a.activity_type)} · ${esc(a.summary)}</strong>${a.details?`<p>${esc(a.details)}</p>`:''}<small>${esc(a.created_at)}${a.createdByName?' · '+esc(a.createdByName):''}</small></article>`).join(''):'<div class="empty">No activity yet.</div>'}</div></div>`;if(cfg.canManage)bindDrawer(l)}
function editForm(l){return `<div class="section"><h3>Pipeline controls</h3><div class="form-grid"><div><small>Stage</small><select class="field" id="fStage">${stages.map(s=>`<option value="${s}" ${s===l.stage?'selected':''}>${labels[s]}</option>`).join('')}</select></div><div><small>Assigned to</small><select class="field" id="fAssigned"><option value="">Unassigned</option>${users.map(u=>`<option value="${u.id}" ${Number(l.assignedTo)===Number(u.id)?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></div><div><small>Estimated value</small><input class="field" id="fValue" type="number" step=".01" value="${l.estimatedValue??''}"></div><div><small>Probability %</small><input class="field" id="fProbability" type="number" min="0" max="100" value="${l.probability}"></div><div class="wide"><small>Next follow-up</small><input class="field" id="fFollowup" type="datetime-local" value="${l.nextFollowupAt?String(l.nextFollowupAt).replace(' ','T').slice(0,16):''}"></div><div class="wide"><small>Internal notes</small><textarea class="field" id="fNotes" rows="4">${esc(l.notes||'')}</textarea></div><div class="wide"><small>Loss reason</small><input class="field" id="fLoss" value="${esc(l.lossReason||'')}"></div></div><div style="display:flex;gap:8px;margin-top:10px"><button class="btn primary" id="saveLead">Save opportunity</button><a class="btn" href="wholesale-purchasing.php?id=${encodeURIComponent(l.id)}">Purchasing Planner</a><button class="btn" id="archiveLead">Archive</button></div></div>`}
function activityForm(){return `<div class="form-grid"><select class="field" id="aType"><option>note</option><option>call</option><option>email</option><option>meeting</option><option>sample</option><option>quote</option><option>followup</option></select><input class="field" id="aSummary" placeholder="Activity summary"><textarea class="field wide" id="aDetails" rows="3" placeholder="Details"></textarea></div><button class="btn" id="addActivity" style="margin-top:8px">Add activity</button>`}
function bindDrawer(l){document.getElementById('fStage').addEventListener('change',async e=>{if(e.target.value!==l.stage){await moveStage(l.id,e.target.value)}});document.getElementById('saveLead').onclick=async()=>{await api('api/wholesale.php',{method:'POST',body:JSON.stringify({action:'update',id:l.id,assignedTo:document.getElementById('fAssigned').value,estimatedValue:document.getElementById('fValue').value,probability:document.getElementById('fProbability').value,nextFollowupAt:document.getElementById('fFollowup').value,notes:document.getElementById('fNotes').value,lossReason:document.getElementById('fLoss').value,csrf_token:cfg.csrf})});toast('Opportunity saved');await load()};document.getElementById('addActivity').onclick=async()=>{const summary=document.getElementById('aSummary').value.trim();if(!summary)return;await api('api/wholesale.php',{method:'POST',body:JSON.stringify({action:'activity',id:l.id,activityType:document.getElementById('aType').value,summary,details:document.getElementById('aDetails').value,csrf_token:cfg.csrf})});toast('Activity added');await openLead(l.id)};document.getElementById('archiveLead').onclick=async()=>{if(!confirm('Archive this wholesale lead?'))return;await api('api/wholesale.php',{method:'POST',body:JSON.stringify({action:'archive',id:l.id,csrf_token:cfg.csrf})});activeId='';document.getElementById('drawer').classList.remove('open');toast('Lead archived');await load()}}
document.getElementById('drawerClose').onclick=()=>document.getElementById('drawer').classList.remove('open');document.getElementById('refresh').onclick=load;document.getElementById('search').addEventListener('input',renderBoard);document.getElementById('stageFilter').innerHTML='<option value="">All stages</option>'+stages.map(s=>`<option value="${s}">${labels[s]}</option>`).join('');document.getElementById('stageFilter').addEventListener('change',renderBoard);document.getElementById('clearSearch').onclick=()=>{document.getElementById('search').value='';document.getElementById('stageFilter').value='';renderBoard()};load().catch(e=>alert(e.message));})();
</script>
</body></html>
